#!/usr/bin/env python3
# =====================================================================
#  apply_gtt_verify_strict.py  —  fence GTT_VERIFY_STRICT_20261112
#
#  ⚠ LIVE ORDER PATH — every strategy that uses GTTs (Icarus, Timberwolf,
#  BB, HA, BRK, Scalp V3/V5). Velvet and Tigris place no GTTs.
#
#  12 Nov 2026, IC_V2 LIVE (friend): yesterday's condor carried overnight
#  with two GTTs — L1's cost-stop (BUY 25750CE @93.50, re-pinned after
#  L2's SL) and L2·ADJ's OCO (SELL 24850PE 63.25/180.70). The pre-market
#  teardown ran BEFORE the day's Kite login: every cancel raised, and
#  cancel_gtt_verified() read the GTT list with get_gtts(), which answers
#  [] when it cannot read — so it reported both "CONFIRMED_GONE". The app
#  forgot their ids, squared both legs off at 09:16 with nothing left to
#  cancel, and both GTTs stayed armed; the OCO later fired and SOLD 195 of
#  a strike the app had already closed.
#
#   zerodha_executor.py  cancel_gtt_verified is FAIL-CLOSED: only a READABLE
#                        list can prove a GTT gone; unreadable after every
#                        retry = not verified (the caller keeps the id,
#                        alerts and retries). Every strategy already treats
#                        "not verified" safely (IC/TMA2: keep id, defer or
#                        forced-flatten with a CRITICAL "delete in Kite").
#   execution_router.py  forwards get_gtts_or_none (it was missing: IC's and
#                        HA's strict reads silently fell back under the router)
#   ic_group_manager.py  * pre-market: if Kite isn't readable yet, don't try
#                          and don't forget anything; retry; ONE alert a day,
#                          only from 09:10 (it used to fire every poll)
#                        * closing sweep: when a live group closes, any ACTIVE
#                          GTT on one of its symbols, for one of its leg
#                          quantities, while that symbol is FLAT at the broker,
#                          is cancelled (verified) + alerted. A symbol another
#                          strategy still holds is never touched; an
#                          unreadable broker = retried, never guessed.
#   tests  execution/test_gtt_verify_strict.py (17 checks; the old executor
#          fails 6 with the exact 12 Nov log lines) · ic/test_ic_gtt_strict.py
#          (the 11→12 Nov carry replayed: L1 SL → L2 cost-stop → L1·ADJ OCO →
#          carry → pre-market before login → 09:16 close; + lost-id sweep,
#          held-symbol and unreadable-broker cases) · the IC, TMA2, TSG, VET,
#          router, latency, wing and slippage suites
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_gtt_verify_strict.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "GTT_VERIFY_STRICT_20261112"
ITEMS = json.loads(r'''[{"path": "backend/app/execution/zerodha_executor.py", "orig": "43cd4932151742bd652ea8f4910caba653cfada53d10b4d4e35d3bf3dd4f58ef", "new": "6af0ded61db39acb0e032444a0d5d5c8f8ef89eaabf840172637032aafdd886d", "blob": ""}, {"path": "backend/app/execution/execution_router.py", "orig": "1fd1e8dd2986e1cd6c8d46c8e357fa6d5968c2a989aa55e08cf99563999e9834", "new": "c740a0fb99199f42255b444b12f280bb6c101e4fbc9616a8c675b4ea92736eb5", "blob": ""}, {"path": "backend/app/engine/ic/ic_group_manager.py", "orig": "f8fea7b17625949d8446023b58831c6d5ff6b8c7cb05f459fcb0c016a2324c3f", "new": "8690a960c76043a5c021105a18b0cd0a4fa9af0a4f6678ce20d24b72b79edc9c", "blob": ""}, {"path": "backend/app/execution/test_execution_router_contract.py", "orig": "aecb447a097045f4b9f1f9779f979dbe132cd7f2451072dbf08f91f0d5132232", "new": "c75ad1d08d0b8e8bb5b4a959c2c3face4d73d2727ec319caba37d92dbd60665c", "blob": ""}, {"path": "backend/app/execution/test_gtt_verify_strict.py", "orig": null, "new": "a6508bb881baf9024b6311cadab151640d1fd1e9daa3e8b045a970cf6a1d568a", "blob": ""}, {"path": "backend/app/engine/ic/test_ic_gtt_strict.py", "orig": null, "new": "26d5e76e07b03441475d330ace605d35c8c04d2a28f585fe87c615a725d1dfd2", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/execution/test_gtt_verify_strict.py", "app/engine/ic/test_ic_gtt_strict.py",
         "app/execution/test_execution_router_contract.py", "app/execution/test_order_latency.py",
         "app/execution/test_wing_fast_fill.py", "app/slippage/test_slip.py",
         "app/engine/tma2/test_tma2_e2e.py", "app/engine/tma2/test_tma2_exit_paths.py",
         "app/engine/tsg/test_tsg_e2e.py", "app/engine/vet/test_vet_e2e.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="gtt_verify_strict_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend)
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=600)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_gtt_verify_strict.py --rollback")
